     9→
    10→#[derive(Debug, PartialEq)]
    11→pub enum Error {
    12→    BeaconStateError(BeaconStateError),
    13→    EpochProcessingError(EpochProcessingError),
    14→    ArithError(ArithError),
    15→    InconsistentStateFork(InconsistentFork),
    16→}
    17→
    18→impl From<ArithError> for Error {
    19→    fn from(e: ArithError) -> Self {
    20→        Self::ArithError(e)
    21→    }
    22→}
    23→
    24→/// Advances a state forward by one slot, performing per-epoch processing if required.
    25→///
    26→/// If the root of the supplied `state` is known, then it can be passed as `state_root`. If
    27→/// `state_root` is `None`, the root of `state` will be computed using a cached tree hash.
    28→/// Providing the `state_root` makes this function several orders of magnitude faster.
    29→#[instrument(level = "debug", skip_all)]
    30→pub fn per_slot_processing<E: EthSpec>(
    31→    state: &mut BeaconState<E>,
    32→    state_root: Option<Hash256>,
    33→    spec: &ChainSpec,
    34→) -> Result<Option<EpochProcessingSummary<E>>, Error> {
    35→    // Verify that the `BeaconState` instantiation matches the fork at `state.slot()`.
    36→    state
    37→        .fork_name(spec)
    38→        .map_err(Error::InconsistentStateFork)?;
    39→
    40→    cache_state(state, state_root)?;
    41→
    42→    let summary = if state.slot() > spec.genesis_slot
    43→        && state.slot().safe_add(1)?.safe_rem(E::slots_per_epoch())? == 0
    44→    {
    45→        Some(per_epoch_processing(state, spec)?)
    46→    } else {
    47→        None
    48→    };
    49→
    50→    state.slot_mut().safe_add_assign(1)?;
    51→
    52→    // Process fork upgrades here. Note that multiple upgrades can potentially run
    53→    // in sequence if they are scheduled in the same Epoch (common in testnets)
    54→    if state.slot().safe_rem(E::slots_per_epoch())? == 0 {
    55→        // If the Altair fork epoch is reached, perform an irregular state upgrade.
    56→        if spec.altair_fork_epoch == Some(state.current_epoch()) {
    57→            upgrade_to_altair(state, spec)?;
    58→        }
    59→        // If the Bellatrix fork epoch is reached, perform an irregular state upgrade.
    60→        if spec.bellatrix_fork_epoch == Some(state.current_epoch()) {
    61→            upgrade_to_bellatrix(state, spec)?;
    62→        }
    63→        // Capella.
    64→        if spec.capella_fork_epoch == Some(state.current_epoch()) {
    65→            upgrade_to_capella(state, spec)?;
    66→        }
    67→        // Deneb.
    68→        if spec.deneb_fork_epoch == Some(state.current_epoch()) {
    69→            upgrade_to_deneb(state, spec)?;
    70→        }
    71→        // Electra.
    72→        if spec.electra_fork_epoch == Some(state.current_epoch()) {
    73→            upgrade_to_electra(state, spec)?;
    74→        }
    75→
    76→        // Fulu.
    77→        if spec.fulu_fork_epoch == Some(state.current_epoch()) {
    78→            upgrade_to_fulu(state, spec)?;
    79→        }
    80→
    81→        // Gloas.
    82→        if spec.gloas_fork_epoch == Some(state.current_epoch()) {
    83→            upgrade_to_gloas(state, spec)?;
    84→        }
    85→
    86→        // Additionally build all caches so that all valid states that are advanced always have
    87→        // committee caches built, and we don't have to worry about initialising them at higher
    88→        // layers.
    89→        state.build_caches(spec)?;
    90→    }
    91→
    92→    Ok(summary)
    93→}
    94→
    95→#[instrument(skip_all)]
    96→fn cache_state<E: EthSpec>(
    97→    state: &mut BeaconState<E>,
    98→    state_root: Option<Hash256>,
    99→) -> Result<(), Error> {
   100→    let previous_state_root = if let Some(root) = state_root {
   101→        root
   102→    } else {
   103→        state.update_tree_hash_cache()?
